import { createClient } from '@/utils/supabase/server'
import { notFound, redirect } from 'next/navigation'
import Link from 'next/link' 

export default async function ReportDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const supabase = createClient()
  const { data: { user } } = await supabase.auth.getUser()
  
  if (!user) return redirect('/login')

  // 1. Fetch Report
  const { data: reportData, error } = await supabase
    .from('demerit_reports')
    .select(`
        *,
        subject:profiles!subject_cadet_id(first_name, last_name, company:companies(company_name)),
        submitter:profiles!submitted_by(first_name, last_name),
        offense_type(offense_name, demerits)
    `)
    .eq('id', id)
    .single()

  if (error || !reportData) {
      // Log the error to your terminal for debugging
      console.error("Error fetching report:", error)
      return notFound()
  }

  const report = reportData as any; 

  // 2. Check Viewer Role
  const { data: profile } = await supabase.from('profiles').select('role:roles(default_role_level)').eq('id', user.id).single()
  const roleLevel = (profile?.role as any)?.default_role_level || 0
  const isStaff = roleLevel >= 50

  return (
    <div className="max-w-4xl mx-auto p-4 sm:p-6">
        {/* HEADER */}
        <div className="flex justify-between items-center mb-6">
            <h1 className="text-2xl font-bold dark:text-white">Report Details</h1>
            <div className="flex gap-2">
                
                {/* Incident Link Button */}
                {isStaff && report.linked_incident_id && (
                    <Link 
                        href={`/incidents/${report.linked_incident_id}`}
                        className="bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200 px-3 py-2 rounded-md text-sm font-bold border border-orange-200 hover:bg-orange-200 transition-colors flex items-center gap-2"
                    >
                        <span>⚠️ View Original Incident</span>
                    </Link>
                )}

                <Link href="/" className="text-gray-500 hover:text-gray-700 px-3 py-2">Back</Link>
            </div>
        </div>

        {/* DETAILS CARD */}
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 space-y-4">
            <div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-1">
                    {report.offense_type?.offense_name || 'Report'}
                </h2>
                <span className={`px-2 py-1 rounded-full text-xs font-bold uppercase ${report.status === 'completed' ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'}`}>
                    {report.status}
                </span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-sm border-t border-gray-100 dark:border-gray-700 pt-4">
                <div>
                    <span className="block text-gray-500 text-xs uppercase font-bold">Cadet</span>
                    <span className="text-gray-900 dark:text-white font-medium">{report.subject?.last_name}, {report.subject?.first_name}</span>
                    <span className="block text-gray-500 text-xs">{report.subject?.company?.company_name}</span>
                </div>
                <div>
                    <span className="block text-gray-500 text-xs uppercase font-bold">Submitted By</span>
                    <span className="text-gray-900 dark:text-white font-medium">{report.submitter?.last_name}, {report.submitter?.first_name}</span>
                    <span className="block text-gray-500 text-xs">{new Date(report.created_at).toLocaleDateString()}</span>
                </div>
            </div>

            <div className="border-t border-gray-100 dark:border-gray-700 pt-4">
                <span className="block text-gray-500 text-xs uppercase font-bold mb-1">Description / Notes</span>
                <p className="text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                    {report.notes || <span className="italic text-gray-400">No notes provided.</span>}
                </p>
            </div>
        </div>
    </div>
  )
}